      "ur": "اے ایمان والو! اللہ تعالیٰ کے شعائر کی بے حرمتی نہ کرو[1] نہ ادب والے مہینوں کی[2] نہ حرم میں قربان ہونے والے اور پٹے پہنائے گئے جانوروں کی جو کعبہ کو جا رہے ہوں[3] اور نہ ان لوگوں کی جو بیت اللہ کے قصد سے اپنے رب تعالیٰ کے فضل اور اس کی رضاجوئی کی نیت سے جا رہے ہوں[4]، ہاں جب تم احرام اتار ڈالو تو شکار کھیل سکتے ہو[5]، جن لوگوں نے تمہیں مسجد حرام سے روکا تھا ان کی دشمنی تمہیں اس بات پر آماده نہ کرے کہ تم حد سے گزر جاؤ[6]، نیکی اور پرہیزگاری میں ایک دوسرے کی امداد کرتے رہو اور گناه اور ﻇلم و زیادتی میں مدد نہ کرو[7]، اور اللہ تعالیٰ سے ڈرتے رہو، بےشک اللہ تعالیٰ سخت سزا دینے واﻻ ہے۔",
      "en": "O you who have believed, do not violate the rites of Allāh or [the sanctity of] the sacred month or [neglect the marking of] the sacrificial animals and garlanding [them] or [violate the safety of] those coming to the Sacred House seeking bounty from their Lord and [His] approval. But when you come out of iḥrām, then [you may] hunt. And do not let the hatred of a people for having obstructed you from al-Masjid al-Ḥarām lead you to transgress. And cooperate in righteousness and piety, but do not cooperate in sin and aggression. And fear Allāh; indeed, Allāh is severe in penalty.",
