      "arFull": "یَسْـَٔلُوْنَكَ مَاذَاۤ اُحِلَّ لَهُمْ ؕ قُلْ اُحِلَّ لَكُمُ الطَّیِّبٰتُ ۙ وَمَا عَلَّمْتُمْ مِّنَ الْجَوَارِحِ مُكَلِّبِیْنَ تُعَلِّمُوْنَهُنَّ مِمَّا عَلَّمَكُمُ اللّٰهُ ؗ فَكُلُوْا مِمَّاۤ اَمْسَكْنَ عَلَیْكُمْ وَاذْكُرُوا اسْمَ اللّٰهِ عَلَیْهِ ۪ وَاتَّقُوا اللّٰهَ ؕ اِنَّ اللّٰهَ سَرِیْعُ الْحِسَابِ ۟",
      "ur": "آپ سے دریافت کرتے ہیں کہ ان کے لئے کیا کچھ حلال ہے؟ آپ کہہ دیجئے کہ تمام پاک چیزیں تمہارے لئے حلال کی گئی ہیں[1] ، اور جن شکار کھیلنے والے جانوروں کو تم نے سدھا رکھا ہے یعنی جنہیں تم تھوڑا بہت وه سکھاتے ہو جس کی تعلیم اللہ تعالیٰ نے تمہیں دے رکھی ہے[2] پس جس شکار کو وه تمہارے لئے پکڑ کر روک رکھیں تو تم اس سے کھا لو اور اس پر اللہ تعالیٰ کے نام کا ذکر کر لیا کرو[3]۔ اور اللہ تعالیٰ سے ڈرتے رہو، یقیناً اللہ تعالیٰ جلد حساب لینے واﻻ ہے۔",
      "en": "They ask you, [O Muḥammad], what has been made lawful for them. Say, \"Lawful for you are [all] good foods and [game caught by] what you have trained of hunting animals[243] which you train as Allāh has taught you. So eat of what they catch for you, and mention the name of Allāh upon it, and fear Allāh.\" Indeed, Allāh is swift in account.",
