      "arFull": "اَلْیَوْمَ اُحِلَّ لَكُمُ الطَّیِّبٰتُ ؕ وَطَعَامُ الَّذِیْنَ اُوْتُوا الْكِتٰبَ حِلٌّ لَّكُمْ ۪ وَطَعَامُكُمْ حِلٌّ لَّهُمْ ؗ وَالْمُحْصَنٰتُ مِنَ الْمُؤْمِنٰتِ وَالْمُحْصَنٰتُ مِنَ الَّذِیْنَ اُوْتُوا الْكِتٰبَ مِنْ قَبْلِكُمْ اِذَاۤ اٰتَیْتُمُوْهُنَّ اُجُوْرَهُنَّ مُحْصِنِیْنَ غَیْرَ مُسٰفِحِیْنَ وَلَا مُتَّخِذِیْۤ اَخْدَانٍ ؕ وَمَنْ یَّكْفُرْ بِالْاِیْمَانِ فَقَدْ حَبِطَ عَمَلُهٗ ؗ وَهُوَ فِی الْاٰخِرَةِ مِنَ الْخٰسِرِیْنَ ۟۠",
      "ur": "کل پاکیزه چیزیں آج تمہارے لئے حلال کی گئیں اور اہل کتاب کا ذبیحہ تمہارے لئے حلال ہے[1] اور تمہارا ذبیحہ ان کے لئے حلال ہے، اور پاک دامن مسلمان عورتیں اور جو لوگ تم سے پہلے کتاب دیئے گئے ہیں ان کی پاک دامن عورتیں بھی حلال ہیں[2] جب کہ تم ان کے مہر ادا کرو، اس طرح کہ تم ان سے باقاعده نکاح کرو یہ نہیں کہ علانیہ زنا کرو یا پوشیده بدکاری کرو، منکرین ایمان کے اعمال ضائع اور اکارت ہیں اور آخرت میں وه ہارنے والوں میں سے ہیں۔",
