      "number": 8,
      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا كُوْنُوْا قَوّٰمِیْنَ لِلّٰهِ شُهَدَآءَ بِالْقِسْطِ ؗ وَلَا یَجْرِمَنَّكُمْ شَنَاٰنُ قَوْمٍ عَلٰۤی اَلَّا تَعْدِلُوْا ؕ اِعْدِلُوْا ۫ هُوَ اَقْرَبُ لِلتَّقْوٰی ؗ وَاتَّقُوا اللّٰهَ ؕ اِنَّ اللّٰهَ خَبِیْرٌ بِمَا تَعْمَلُوْنَ ۟",
