      "arFull": "وَعَدَ اللّٰهُ الَّذِیْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ ۙ لَهُمْ مَّغْفِرَةٌ وَّاَجْرٌ عَظِیْمٌ ۟",
