      "arFull": "فَبِمَا نَقْضِهِمْ مِّیْثَاقَهُمْ لَعَنّٰهُمْ وَجَعَلْنَا قُلُوْبَهُمْ قٰسِیَةً ۚ یُحَرِّفُوْنَ الْكَلِمَ عَنْ مَّوَاضِعِهٖ ۙ وَنَسُوْا حَظًّا مِّمَّا ذُكِّرُوْا بِهٖ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلٰی خَآىِٕنَةٍ مِّنْهُمْ اِلَّا قَلِیْلًا مِّنْهُمْ فَاعْفُ عَنْهُمْ وَاصْفَحْ ؕ اِنَّ اللّٰهَ یُحِبُّ الْمُحْسِنِیْنَ ۟",
