      "number": 17,
      "arFull": "لَقَدْ كَفَرَ الَّذِیْنَ قَالُوْۤا اِنَّ اللّٰهَ هُوَ الْمَسِیْحُ ابْنُ مَرْیَمَ ؕ قُلْ فَمَنْ یَّمْلِكُ مِنَ اللّٰهِ شَیْـًٔا اِنْ اَرَادَ اَنْ یُّهْلِكَ الْمَسِیْحَ ابْنَ مَرْیَمَ وَاُمَّهٗ وَمَنْ فِی الْاَرْضِ جَمِیْعًا ؕ وَلِلّٰهِ مُلْكُ السَّمٰوٰتِ وَالْاَرْضِ وَمَا بَیْنَهُمَا ؕ یَخْلُقُ مَا یَشَآءُ ؕ وَاللّٰهُ عَلٰی كُلِّ شَیْءٍ قَدِیْرٌ ۟",
