      "arFull": "قَالَ رَجُلٰنِ مِنَ الَّذِیْنَ یَخَافُوْنَ اَنْعَمَ اللّٰهُ عَلَیْهِمَا ادْخُلُوْا عَلَیْهِمُ الْبَابَ ۚ فَاِذَا دَخَلْتُمُوْهُ فَاِنَّكُمْ غٰلِبُوْنَ ۚ۬ وَعَلَی اللّٰهِ فَتَوَكَّلُوْۤا اِنْ كُنْتُمْ مُّؤْمِنِیْنَ ۟",
