      "arFull": "لَىِٕنْۢ بَسَطْتَّ اِلَیَّ یَدَكَ لِتَقْتُلَنِیْ مَاۤ اَنَا بِبَاسِطٍ یَّدِیَ اِلَیْكَ لِاَقْتُلَكَ ۚ اِنِّیْۤ اَخَافُ اللّٰهَ رَبَّ الْعٰلَمِیْنَ ۟",
