      "arFull": "اِنَّمَا جَزٰٓؤُا الَّذِیْنَ یُحَارِبُوْنَ اللّٰهَ وَرَسُوْلَهٗ وَیَسْعَوْنَ فِی الْاَرْضِ فَسَادًا اَنْ یُّقَتَّلُوْۤا اَوْ یُصَلَّبُوْۤا اَوْ تُقَطَّعَ اَیْدِیْهِمْ وَاَرْجُلُهُمْ مِّنْ خِلَافٍ اَوْ یُنْفَوْا مِنَ الْاَرْضِ ؕ ذٰلِكَ لَهُمْ خِزْیٌ فِی الدُّنْیَا وَلَهُمْ فِی الْاٰخِرَةِ عَذَابٌ عَظِیْمٌ ۟ۙ",
      "ur": "جو اللہ تعالیٰ سے اور اس کے رسول سے لڑیں اور زمین میں فساد کرتے پھریں ان کی سزا یہی ہے کہ وه قتل کر دیئے جائیں یا سولی چڑھا دیئے جائیں یا مخالف جانب سے ان کے ہاتھ پاوں کاٹ دیئے جائیں، یا انہیں جلاوطن کر دیا جائے[1] ، یہ تو ہوئی ان کی دنیوی ذلت اور خواری، اور آخرت میں ان کے لئے بڑا بھاری عذاب ہے۔",
      "en": "Indeed, the penalty[262] for those who wage war[263] against Allāh and His Messenger and strive upon earth [to cause] corruption is none but that they be killed or crucified or that their hands and feet be cut off from opposite sides or that they be exiled from the land. That is for them a disgrace in this world; and for them in the Hereafter is a great punishment,",
