      "arFull": "سَمّٰعُوْنَ لِلْكَذِبِ اَكّٰلُوْنَ لِلسُّحْتِ ؕ فَاِنْ جَآءُوْكَ فَاحْكُمْ بَیْنَهُمْ اَوْ اَعْرِضْ عَنْهُمْ ۚ وَاِنْ تُعْرِضْ عَنْهُمْ فَلَنْ یَّضُرُّوْكَ شَیْـًٔا ؕ وَاِنْ حَكَمْتَ فَاحْكُمْ بَیْنَهُمْ بِالْقِسْطِ ؕ اِنَّ اللّٰهَ یُحِبُّ الْمُقْسِطِیْنَ ۟",
      "ur": "یہ کان لگا لگا کر جھوٹ کے سننے والے[1] اور جی بھر بھر کر حرام کے کھانے والے ہیں، اگر یہ تمہارے پاس آئیں تو تمہیں اختیار ہے خواه ان کے آپس کا فیصلہ کرو خواه ان کو ٹال دو، اگر تم ان سے منھ بھی پھیرو گے تو بھی یہ تم کو ہرگز کوئی ضرر نہیں پہنچا سکتے، اور اگر تم فیصلہ کرو تو ان میں عدل وانصاف کے ساتھ فیصلہ کرو، یقیناً عدل والوں کے ساتھ اللہ محبت رکھتا ہے۔",
