      "number": 45,
      "arFull": "وَكَتَبْنَا عَلَیْهِمْ فِیْهَاۤ اَنَّ النَّفْسَ بِالنَّفْسِ ۙ وَالْعَیْنَ بِالْعَیْنِ وَالْاَنْفَ بِالْاَنْفِ وَالْاُذُنَ بِالْاُذُنِ وَالسِّنَّ بِالسِّنِّ ۙ وَالْجُرُوْحَ قِصَاصٌ ؕ فَمَنْ تَصَدَّقَ بِهٖ فَهُوَ كَفَّارَةٌ لَّهٗ ؕ وَمَنْ لَّمْ یَحْكُمْ بِمَاۤ اَنْزَلَ اللّٰهُ فَاُولٰٓىِٕكَ هُمُ الظّٰلِمُوْنَ ۟",
      "ur": "اور ہم نے یہودیوں کے ذمہ تورات میں یہ بات مقرر کر دی تھی کہ جان کے بدلے جان اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور خاص زخموں کا بھی بدلہ ہے[1] ، پھر جو شخص اس کو معاف کردے تو وه اس کے لئے کفاره ہے، اور جو لوگ اللہ کے نازل کئے ہوئے کے مطابق حکم نہ کریں، وہی لوگ ﻇالم ہیں۔[2]",
      "en": "And We ordained for them therein a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and for wounds is legal retribution. But whoever gives [up his right as] charity, it is an expiation for him. And whoever does not judge by what Allāh has revealed - then it is those who are the wrongdoers [i.e., the unjust].",
