      "arFull": "وَقَفَّیْنَا عَلٰۤی اٰثَارِهِمْ بِعِیْسَی ابْنِ مَرْیَمَ مُصَدِّقًا لِّمَا بَیْنَ یَدَیْهِ مِنَ التَّوْرٰىةِ ۪ وَاٰتَیْنٰهُ الْاِنْجِیْلَ فِیْهِ هُدًی وَّنُوْرٌ ۙ وَّمُصَدِّقًا لِّمَا بَیْنَ یَدَیْهِ مِنَ التَّوْرٰىةِ وَهُدًی وَّمَوْعِظَةً لِّلْمُتَّقِیْنَ ۟ؕ",
