      "number": 47,
      "arFull": "وَلْیَحْكُمْ اَهْلُ الْاِنْجِیْلِ بِمَاۤ اَنْزَلَ اللّٰهُ فِیْهِ ؕ وَمَنْ لَّمْ یَحْكُمْ بِمَاۤ اَنْزَلَ اللّٰهُ فَاُولٰٓىِٕكَ هُمُ الْفٰسِقُوْنَ ۟",
      "ur": "اور انجیل والوں کو بھی چاہئے کہ اللہ تعالیٰ نے جو کچھ انجیل میں نازل فرمایا ہے اسی کے مطابق حکم کریں[1] اور جو اللہ تعالیٰ کے نازل کرده سے ہی حکم نہ کریں وه (بدکار) فاسق ہیں۔",
      "en": "And let the People of the Gospel judge by what Allāh has revealed therein. And whoever does not judge by what Allāh has revealed - then it is those who are the defiantly disobedient.",
