      "arFull": "اَفَحُكْمَ الْجَاهِلِیَّةِ یَبْغُوْنَ ؕ وَمَنْ اَحْسَنُ مِنَ اللّٰهِ حُكْمًا لِّقَوْمٍ یُّوْقِنُوْنَ ۟۠",
