      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا مَنْ یَّرْتَدَّ مِنْكُمْ عَنْ دِیْنِهٖ فَسَوْفَ یَاْتِی اللّٰهُ بِقَوْمٍ یُّحِبُّهُمْ وَیُحِبُّوْنَهٗۤ ۙ اَذِلَّةٍ عَلَی الْمُؤْمِنِیْنَ اَعِزَّةٍ عَلَی الْكٰفِرِیْنَ ؗ یُجَاهِدُوْنَ فِیْ سَبِیْلِ اللّٰهِ وَلَا یَخَافُوْنَ لَوْمَةَ لَآىِٕمٍ ؕ ذٰلِكَ فَضْلُ اللّٰهِ یُؤْتِیْهِ مَنْ یَّشَآءُ ؕ وَاللّٰهُ وَاسِعٌ عَلِیْمٌ ۟",
