      "arFull": "وَاِذَا نَادَیْتُمْ اِلَی الصَّلٰوةِ اتَّخَذُوْهَا هُزُوًا وَّلَعِبًا ؕ ذٰلِكَ بِاَنَّهُمْ قَوْمٌ لَّا یَعْقِلُوْنَ ۟",
