      "number": 68,
      "arFull": "قُلْ یٰۤاَهْلَ الْكِتٰبِ لَسْتُمْ عَلٰی شَیْءٍ حَتّٰی تُقِیْمُوا التَّوْرٰىةَ وَالْاِنْجِیْلَ وَمَاۤ اُنْزِلَ اِلَیْكُمْ مِّنْ رَّبِّكُمْ ؕ وَلَیَزِیْدَنَّ كَثِیْرًا مِّنْهُمْ مَّاۤ اُنْزِلَ اِلَیْكَ مِنْ رَّبِّكَ طُغْیَانًا وَّكُفْرًا ۚ فَلَا تَاْسَ عَلَی الْقَوْمِ الْكٰفِرِیْنَ ۟",
