      "arFull": "مَا الْمَسِیْحُ ابْنُ مَرْیَمَ اِلَّا رَسُوْلٌ ۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ ؕ وَاُمُّهٗ صِدِّیْقَةٌ ؕ كَانَا یَاْكُلٰنِ الطَّعَامَ ؕ اُنْظُرْ كَیْفَ نُبَیِّنُ لَهُمُ الْاٰیٰتِ ثُمَّ انْظُرْ اَنّٰی یُؤْفَكُوْنَ ۟",
