      "arFull": "مَا عَلَی الرَّسُوْلِ اِلَّا الْبَلٰغُ ؕ وَاللّٰهُ یَعْلَمُ مَا تُبْدُوْنَ وَمَا تَكْتُمُوْنَ ۟",
