      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا عَلَیْكُمْ اَنْفُسَكُمْ ۚ لَا یَضُرُّكُمْ مَّنْ ضَلَّ اِذَا اهْتَدَیْتُمْ ؕ اِلَی اللّٰهِ مَرْجِعُكُمْ جَمِیْعًا فَیُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُوْنَ ۟",
