      "number": 106,
      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا شَهَادَةُ بَیْنِكُمْ اِذَا حَضَرَ اَحَدَكُمُ الْمَوْتُ حِیْنَ الْوَصِیَّةِ اثْنٰنِ ذَوَا عَدْلٍ مِّنْكُمْ اَوْ اٰخَرٰنِ مِنْ غَیْرِكُمْ اِنْ اَنْتُمْ ضَرَبْتُمْ فِی الْاَرْضِ فَاَصَابَتْكُمْ مُّصِیْبَةُ الْمَوْتِ ؕ تَحْبِسُوْنَهُمَا مِنْ بَعْدِ الصَّلٰوةِ فَیُقْسِمٰنِ بِاللّٰهِ اِنِ ارْتَبْتُمْ لَا نَشْتَرِیْ بِهٖ ثَمَنًا وَّلَوْ كَانَ ذَا قُرْبٰی ۙ وَلَا نَكْتُمُ شَهَادَةَ ۙ اللّٰهِ اِنَّاۤ اِذًا لَّمِنَ الْاٰثِمِیْنَ ۟",
      "ur": "اے ایمان والو! تمہارے آپس میں دو شخص کا گواه ہونا مناسب ہے جبکہ تم میں سے کسی کو موت آنے لگے اور وصیت کرنے کا وقت ہو وه دو شخص ایسے ہوں کہ دیندار ہوں خواه تم میں سے ہوں[1] یا غیر لوگوں میں سے دو شخص ہوں اگر تم کہیں سفر میں گئے ہو اور تمہیں موت آ جائے[2] اگر تم کو شبہ ہو تو ان دونوں کو بعد نماز روک لو پھر دونوں اللہ کی قسم کھائیں کہ ہم اس قسم کے عوض کوئی نفع نہیں لینا چاہتے[3] اگر چہ کوئی قرابت دار بھی ہو اور اللہ تعالیٰ کی بات کو ہم پوشیده نہ کریں گے، ہم اس حالت میں سخت گنہگار ہوں گے۔",
      "en": "O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - [that of] two just men from among you or two others from outside if you are traveling through the land and the disaster of death should strike you. Detain them after the prayer and let them both swear by Allāh if you doubt [their testimony, saying], \"We will not exchange it [i.e., our oath] for a price [i.e., worldly gain], even if he should be a near relative, and we will not withhold the testimony of [i.e., ordained by] Allāh. Indeed, we would then be of the sinful.\"",
