      "number": 119,
      "arFull": "قَالَ اللّٰهُ هٰذَا یَوْمُ یَنْفَعُ الصّٰدِقِیْنَ صِدْقُهُمْ ؕ لَهُمْ جَنّٰتٌ تَجْرِیْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِیْنَ فِیْهَاۤ اَبَدًا ؕ رَضِیَ اللّٰهُ عَنْهُمْ وَرَضُوْا عَنْهُ ؕ ذٰلِكَ الْفَوْزُ الْعَظِیْمُ ۟",
      "ur": "اللہ ارشاد فرمائے گا کہ یہ وه دن ہے کہ جو لوگ سچے تھے ان کا سچا ہونا ان کے کام آئے گا[1] ان کو باغ ملیں گے جن کے نیچے نہریں جاری ہوں گی جن میں وه ہمیشہ ہمیشہ کو رہیں گے۔ اللہ تعالیٰ ان سے راضی اور خوش اور یہ اللہ سے راضی اور خوش ہیں، یہ بڑی (بھاری) کامیابی ہے۔",
      "en": "Allāh will say, \"This is the Day when the truthful will benefit from their truthfulness.\" For them are gardens [in Paradise] beneath which rivers flow, wherein they will abide forever, Allāh being pleased with them, and they with Him. That is the great attainment.",
